with.code:
// Tenancy is established HERE and nowhere else. Everything downstream trusts envelope.tenant_id
// absolutely, so this is the one place that must get it right.
const trigger = $execution?.customData?.get?.('trigger') || $json.__trigger || 'unknown';
const TENANT_MAP = JSON.parse($env.MOS_TENANT_MAP || '{}');

let source_channel = 'api', external_id = null, text = '', raw = $json;

if ($json.message || $json.callback_query) {
  source_channel = 'telegram';
  external_id = String($json.message?.chat?.id ?? $json.callback_query?.message?.chat?.id ?? '');
  text = $json.message?.text || $json.message?.caption || '';
} else if ($json.headers) {
  source_channel = $json.body?.source || 'webhook';
  external_id = $json.headers['x-mos-tenant'] || $json.body?.tenant_id || null;
  text = $json.body?.text || $json.body?.prompt || '';
  raw = $json.body;
} else if ($json.__schedule) {
  source_channel = 'schedule';
  external_id = $json.tenant_id;
  text = $json.prompt || '';
}

const tenant = TENANT_MAP[`${source_channel}:${external_id}`] || TENANT_MAP[external_id] || null;
if (!tenant) {
  throw new Error(`POLICY_BLOCKED: unrecognised source ${source_channel}:${external_id} — refusing to process work for an unmapped tenant`);
}

return [{ json: { source_channel, external_id, text, raw, tenant } }];

// One envelope, minted once, carried everywhere. Its policy block is the CEILING for this run:
// downstream units may narrow it, never widen it.
const crypto = require('crypto');
const s = $json;
const t = s.tenant;
const trace_id = 'trc_' + crypto.randomUUID().replace(/-/g, '').slice(0, 20);
const idem = crypto.createHash('sha256').update([t.tenant_id, s.source_channel, s.external_id, s.text, new Date().toISOString().slice(0, 13)].join('|')).digest('hex');

return [{ json: {
  envelope_version: '1.0.0',
  trace_id,
  span_id: 'spn_' + crypto.randomUUID().slice(0, 8),
  parent_span_id: null,
  tenant_id: t.tenant_id,
  brand_id: t.default_brand_id || null,
  vertical: t.vertical || 'generic',
  locale: t.locale || 'en-US',
  region: t.region || 'us',
  intent: 'intake.received',
  stage: 'intake',
  idempotency_key: idem,
  attempt: 1,
  max_attempts: 3,
  deadline_at: new Date(Date.now() + (t.deadline_minutes ?? 30) * 60000).toISOString(),
  policy: {
    autonomy_level: t.autonomy_level || 'publish_with_approval',
    compliance_profile: t.compliance_profile || 'standard',
    approval_mode: t.approval_mode || 'channel_conditional',
    data_residency: t.data_residency || 'any',
    pii_redaction: t.pii_redaction !== false,
    allow_external_research: t.allow_external_research !== false,
    model_tier_cap: t.model_tier_cap || 'frontier'
  },
  budget: {
    currency: t.currency || 'USD',
    cap_minor_units: t.run_budget_minor_units ?? 2000,
    spent_minor_units: 0,
    soft_limit_pct: 0.8,
    on_soft_limit: 'downgrade_tier'
  },
  routing: {},
  payload: { source_channel: s.source_channel, raw: s.raw, text: s.text, reply_to: s.external_id },
  provenance: [],
  error: null
} }];
